function VideoSubtitle:__init()
    self.controller = nil
    self.subtitleSegments = nil  -- 字幕数组
    self.subtitleSegmentsNum = 0 -- 字幕数组 元素个数
    self.currentSegmentIdx = 1     -- 字幕元素 idx; 1-based

    self.isActive = false 
    self.isError = false -- 配表数据严重错误, 直接终止本功能
end


function VideoSubtitle:__delete()
end




function VideoSubtitle:Start()
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    assert( self.CanvasGroup )
    assert( self.ControllerForUI )
    assert( self.TextDesc )
end



function VideoSubtitle:OnDestroy()
    self.OnStatusChangeCallback = nil
    self.subtitleSegments = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function VideoSubtitle:Update()
    if self.isError == true then 
        return
    end 

    if VideoSubtitleUtils.isTotalActive == false or self.isActive == false then 
        return
    end 

    if self.ControllerForUI.player.status == Player.Status.Playing  then
    
        local frameInfo = self.ControllerForUI.player.frameInfo
        local timeInFile = frameInfo.frameNoPerFile / (frameInfo.framerateN/frameInfo.framerateD)
        --print( "koko timeInFile = " .. tostring(timeInFile) )
        self:Do( timeInFile )
    end
end


-- =========================================== Self ================================================ --


function VideoSubtitle:StartPlay( sceneId_ )
    self.isError = false
    self:SetSubtitleSegmentDatas_( sceneId_ )
    self.isActive = true
end 




function VideoSubtitle:EndPlay()
    self.isActive = false
end 



-- todo 读取 字幕数据
function VideoSubtitle:SetSubtitleSegmentDatas_( sceneId_ )

    sceneId_ = VideoSubtitle.GetSceneId(sceneId_)
    print( "koko 解析得字幕段 id = " .. tostring(sceneId_) .. ";" )

    
    -- todo: 拿到字幕数据:
    --self.subtitleSegments = fakeSubtitleSegments
    self.subtitleSegments = VideoSubtitleUtils.ReadVideoSubtitleVO_ByAnimeId( sceneId_ )
    if isNull(self.subtitleSegments) or table.count(self.subtitleSegments)==0 then 
        --printError( "koko 没读到目标视频的 字幕 配表数据" )
        print( "koko == Error ==: 没读到目标视频的 字幕 配表数据" )
        self.isError = true
        return
    end


    -- 插入尾哨兵元素:
    local lastTimeFrom = self.subtitleSegments[table.count(self.subtitleSegments)].timeTo + 0.1
    table.insert(self.subtitleSegments, {
        timeFrom = lastTimeFrom,
        timeTo   = lastTimeFrom + segmentMinDuration,
        text = "",
    })

    self.subtitleSegmentsNum = table.count(self.subtitleSegments)
    self.currentSegmentIdx = 1

    -- 确保各 segments 的 timeFrom 一定是升序排序:
    self:CheckSegmentsBasicOrder_()
    if self.isError == true then 
        return
    end 

    -- 检验并修正 配表数据:
    for l=1, self.subtitleSegmentsNum-1 do -- leftIdx
        local leftSeg  = self.subtitleSegments[l]
        local rightSeg = self.subtitleSegments[l+1]
        self:AdjustSegmentParams( l, leftSeg, rightSeg )
    end

end 



-- 确保各 segments 的 timeFrom 一定是递增的;
function VideoSubtitle:CheckSegmentsBasicOrder_()

    local tmpTimeFrom = self.subtitleSegments[1].timeFrom

    for i=2, self.subtitleSegmentsNum do -- leftIdx
        local newTimeFrom = self.subtitleSegments[i].timeFrom
        if newTimeFrom < tmpTimeFrom + segmentMinDuration then  
            printError( "字幕配表严重错误, timeFrom 数据错乱 " )
            self.isError = true
            return
        end
        tmpTimeFrom = newTimeFrom
    end
end



-- 修正一段 segment 内的 配表数据异常:
function VideoSubtitle:AdjustSegmentParams( idx_, segment_, nextSegment_ )
    
    -- 两个 segment 首尾交叉了:
    if nextSegment_.timeFrom < segment_.timeTo then 
        printError( "字幕配表数据异常:[强] 字幕段:" .. tostring(idx_) .. " 和后端交叉了 " )
        -- 因为在之前的 CheckSegmentsBasicOrder() 检测中, 我们已经保证每两个 timeFrom 之间一定有段间隙: segmentMinDuration, 所以 timeTo 可以放心地往前缩
        segment_.timeTo = nextSegment_.timeFrom - minTimeGap
    end

    -- 本段内部, timeFrom 和 timeTo 颠倒了
    if segment_.timeTo < segment_.timeFrom then 
        printError( "字幕配表数据异常: [强] 字幕段:" .. tostring(idx_) .. " 内部的 timeFrom 和 timeTo 颠倒了" )
        segment_.timeTo = nextSegment_.timeFrom - minTimeGap
    end 


    if (segment_.timeTo - segment_.timeFrom) < segmentMinDuration then 
        printError( "字幕配表数据异常: [弱] 字幕段:" .. tostring(idx_) .. " 内部的 timeFrom 到 timeTo 的时长太短了, 确保大于: " .. tostring(segmentMinDuration) )
        segment_.timeTo = nextSegment_.timeFrom - minTimeGap
    end 

    -- 计算 淡入淡出最大时长:
    local fadeInOutMaxDuration = (segment_.timeTo - segment_.timeFrom) * fadeInOutMaxPercent

    if segment_.fadeIn > fadeInOutMaxDuration then 
        printError( "字幕配表数据异常: [弱] 字幕段:" .. tostring(idx_) .. " 内部 fadeIn 时长过长" )
        segment_.fadeIn = fadeInOutMaxDuration
    end 

    if segment_.fadeOut > fadeInOutMaxDuration then 
        printError( "字幕配表数据异常: [弱] 字幕段:" .. tostring(idx_) .. " 内部 fadeOut 时长过长" )
        segment_.fadeOut = fadeInOutMaxDuration
    end 
end





function VideoSubtitle:SetMainText( str_ )

    if self.TextDesc.text ~= str_ then 
        print( "koko 设置字幕: " .. tostring(str_) )
        self.TextDesc.text = str_
    end     
end


function VideoSubtitle:Do( currentTime_ )

    if self.currentSegmentIdx < 1 or self.currentSegmentIdx > self.subtitleSegmentsNum then 
        printError( "数据异常" )
        self:SetMainText(" ")
        return
    end 
    
    -- 第一段字幕之前:
    if currentTime_ < self.subtitleSegments[1].timeFrom then
        self:SetMainText("--- [未开始] ---")
        --self:SetMainText(" ")
        self.CanvasGroup.alpha = 0.0
        return
    end 

    -- 最后一段字幕之后:
    if currentTime_ >= self.subtitleSegments[self.subtitleSegmentsNum].timeTo then
        self:SetMainText("--- [已结束] ---")
        --self:SetMainText(" ")
        self.CanvasGroup.alpha = 0.0
        return
    end

    --- 找到正确的 当前 字幕段:
    local newSegmentIdx = nil
    for l=self.currentSegmentIdx, self.subtitleSegmentsNum-1 do -- leftIdx 
        local leftSeg  = self.subtitleSegments[l]
        local rightSeg = self.subtitleSegments[l+1]

        if currentTime_ >= leftSeg.timeFrom and currentTime_ < rightSeg.timeFrom then 
            newSegmentIdx = l
            break
        end
    end
    if isNull( newSegmentIdx ) then 
        -- 说明进入 尾哨兵元素区间了, 直接返回
        return
    end 
    self.currentSegmentIdx = newSegmentIdx
    local nowSegment =self.subtitleSegments[self.currentSegmentIdx]

    -- 开始正式处理 segment:
    local fadeInBegin  = nowSegment.timeFrom 
    local fadeInEnd    = nowSegment.timeFrom + nowSegment.fadeIn 
    local fadeOutBegin = nowSegment.timeTo - nowSegment.fadeOut
    local fadeOutEnd   = nowSegment.timeTo

    -- 计算并设置 淡入淡出 alpha 值:
    local alpha = 0
    if currentTime_ < fadeInEnd then 
        -- 淡入:
        alpha = KTool.Remap( fadeInBegin, fadeInEnd, 0.0, 1.0, currentTime_ )

    elseif currentTime_ < fadeOutBegin then
        -- 全显:
        alpha = 1.0

    elseif currentTime_ <= fadeOutEnd then
        -- 淡出:
        alpha = KTool.Remap( fadeOutBegin, fadeOutEnd, 1.0, 0.0, currentTime_ )

    else
        -- 此时位于 不显示阶段
    end 
    self.CanvasGroup.alpha = alpha
    --print( "a = " .. tostring(alpha) )

    --- 配置文本:
    if currentTime_ <= nowSegment.timeTo then 
        self:SetMainText( nowSegment.subtitle )
    else 
        self:SetMainText(" ")
    end
end




function VideoSubtitle:PrintFrameInfo( frameInfo )
    local log =    "koko -- frame:" ..
        "\n     frameNo:  -"                .. tostring(frameInfo.frameNo)              .. "-  Frame identification number (serial number from 0)" ..
        "\n     frameNoPerFile:  -"         .. tostring(frameInfo.frameNoPerFile)       .. "-  Frame identification number (identification number specific to movie files)" ..
        "\n     numImages:  -"              .. tostring(frameInfo.numImages)            .. "-  The number of images included in the frame" ..
        "\n     framerateN:  -"             .. tostring(frameInfo.framerateN)           .. "-  Rational format frame rate (numerator) framerate [x1000] = framerateN / framerateD" ..
        "\n     framerateD:  -"             .. tostring(frameInfo.framerateD)           .. "-  Rational format frame rate (numerator) framerate [x1000] = framerateN / framerateD" ..
        "\n     time:  -"                   .. tostring(frameInfo.time)                 .. "-  Time. Seconds are represented by time/tunit. Continuously added during loop playback or linked playback." ..
        "\n     tunit:  -"                  .. tostring(frameInfo.tunit)                .. "-  Time unit" ..
        "\n     cntConcatenatedMovie:  -"   .. tostring(frameInfo.cntConcatenatedMovie) .. "-  The number of movie concatenation" ..
        "\n     cntSkippedFrames:  -"       .. tostring(frameInfo.cntSkippedFrames)     .. "-  The number of frames skipped in decoding" ..
        "\n     totalFramesPerFile:  -"     .. tostring(frameInfo.totalFramesPerFile)   .. "-  Total number of frames (specific to movie files)";
    print(log)
end







-- 从: "Movie/CS_plot_1002070.usm" 得到 "CS_plot_1002070"
function VideoSubtitle.GetSceneId( src_ )
    -- ========================
    -- -1- 直接走 C# 代码:
    --return KTool.GetFileNameWithoutExtension(src_)

    -- ========================
    -- -2- 自己实现:
    src_ = KTool.NormalizePathSeparator(src_) -- '\\' -> '/'
    local ret = src_:match("[^/]+$") -- get filename: "aa.exe"
    
    local tail = string.find(ret, ".", 1, true ) -- 参数4: 关闭模式匹配
    if isNotNull(tail) and tail~=1 then 
        ret = string.sub( ret, 1, tail-1 )
    end 
    return checkString(ret)
end





